<?php get_header(); ?><section class="cg-page"><h1><?php if(is_archive()){post_type_archive_title();}elseif(is_search()){echo '搜索结果';}else{echo '内容与指南';} ?></h1><div class="cg-grid"><?php while(have_posts()){the_post();?><a class="cg-card" href="<?php the_permalink(); ?>"><span class="cg-badge"><?php echo get_post_meta(get_the_ID(),'_cg_sponsored',true)?'赞助内容':'编辑内容'; ?></span><h2><?php the_title(); ?></h2><p><?php echo esc_html(get_the_excerpt()); ?></p><span class="cg-card-link">查看详情 →</span></a><?php } ?></div><?php if(!have_posts() && !$wp_query->post_count){?><p>内容正在整理中。</p><?php } ?><div class="cg-pagination"><?php the_posts_pagination(); ?></div></section><?php get_footer(); ?>
